import axios from "axios";

const cache = {};

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL,
  timeout: 5000,
  headers: {
    "Content-Type": "application/json"
  }
});

const getCacheKey = (url, config = {}) => {
  const params = config.params ? JSON.stringify(config.params) : "";
  return `${url}${params}`;
};

api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }

  return config;
});

api.interceptors.response.use(
  (response) => {
    const method = response.config?.method?.toLowerCase();
    const url = response.config?.url;

    if (method === "get" && url) {
      cache[getCacheKey(url, response.config)] = response.data;
    }

    if (method && method !== "get") {
      Object.keys(cache).forEach((key) => delete cache[key]);
    }

    return response;
  },
  async (error) => {
    const config = error.config;
    if (!config || config.__retry) {
      throw error;
    }

    config.__retry = true;
    return api(config);
  }
);

const axiosGet = api.get.bind(api);

api.get = async (url, config = {}) => {
  const cacheKey = getCacheKey(url, config);
  if (config.cache !== false && Object.prototype.hasOwnProperty.call(cache, cacheKey)) {
    return {
      data: cache[cacheKey],
      status: 200,
      statusText: "OK",
      headers: {},
      config
    };
  }

  const response = await axiosGet(url, config);
  cache[cacheKey] = response.data;
  return response;
};

api.clearCache = (keys = []) => {
  if (!keys.length) {
    Object.keys(cache).forEach((key) => delete cache[key]);
    return;
  }

  keys.forEach((key) => {
    Object.keys(cache)
      .filter((cacheKey) => cacheKey.startsWith(key))
      .forEach((cacheKey) => delete cache[cacheKey]);
  });
};

export default api;
